class FEMenuEntry
{
public:
	void Disable(bool);
	FEMenuEntry *up;
	FEMenuEntry *down;
};

class GraphicalMenuSystem
{
public:
	bool multiplayer;
	bool multi_1;
};

class FEManager
{
public:
	int tmp_game_mode;
};

class game
{
public:
	int get_player_handicap(int);
	void SetSurferIdx(int, int);
};

class career
{
public:
	bool IsUsingPersonality();
};

extern game *g_game_ptr;
extern career *g_career;

enum
{
	GAME_MODE_CAREER,
	SURFER_LAST = 25
};

class SurferFrontEnd
{
	enum
	{
		DISP_SELECT,
		DISP_HANDICAP,
		DISP_STATS
	};

	int disp_state;
	int availability[SURFER_LAST];
	bool personality_unlocked[SURFER_LAST];
	GraphicalMenuSystem *sys;
	FEMenuEntry *current_surfer;
	FEMenuEntry *Bio;
	FEMenuEntry *Personality;
	FEMenuEntry *Continue;
	FEMenuEntry *Handicap;
	FEManager *manager;

public:
	int current_surfer_index;
	void OnHighlightHero(int old_index);
	void AdjustHandicapAbso(int absolute);
	void SetPersonality(bool up);
	void MaskWave(int wave);
	bool BioAvailable();
};

void SurferFrontEnd::OnHighlightHero(int old_index)
{
	switch(disp_state)
	{
	case DISP_STATS:
		Personality->down = Continue;
		Continue->up = Personality;
		break;
	case DISP_HANDICAP:
		Handicap->up = current_surfer;
		current_surfer->down = Handicap;
		if((sys->multiplayer && sys->multi_1) || (!sys->multiplayer))
			AdjustHandicapAbso(g_game_ptr->get_player_handicap(0));
		else
			AdjustHandicapAbso(g_game_ptr->get_player_handicap(1));
		break;
	case DISP_SELECT:
		Bio->up = current_surfer;
		current_surfer->down = Bio;
		break;
	}

	if(disp_state != DISP_STATS)
	{
		Personality->down = current_surfer;
		current_surfer->up = Personality;
	}

	g_game_ptr->SetSurferIdx(sys->multiplayer && !sys->multi_1 ? 1 : 0, current_surfer_index);

	Personality->Disable(!personality_unlocked[current_surfer_index]);
	bool use_pers = (manager->tmp_game_mode == GAME_MODE_CAREER && g_career->IsUsingPersonality() && personality_unlocked[current_surfer_index]);

	SetPersonality(use_pers);

	for(int i=0; i<4; i++)
		MaskWave(i);

	Bio->Disable(!BioAvailable());
}
